{
  "technical_and_design_decisions": [
    "For U1 and U2: Refactor statebased and entities packages to depend only on fabric protos by removing direct imports of fabric/comm, fabric/protoutil, pkg/errors, and other internal packages. Replace with interfaces or direct protobuf usage where needed.",
    "For U3 and U4: Update the marbles02_private chaincode in fabric-samples by adding comments and modifying export commands to include `tr -d \\\\` to strip backslashes, preventing JSON parsing errors on Windows.",
    "For U5-U8: Create a new Go module `github.com/hyperledger/fabric-lib-go` with subpackages `protoutil`, `bccsp`, `msp`, and `discovery`. Extract these components from the main Fabric repository, ensuring they have no unwanted transitive dependencies. Update the Fabric codebase to depend on this new module.",
    "The externalized libraries will be versioned independently and released separately, allowing the Fabric Go SDK and other consumers to depend on them directly."
  ],
  "assumptions": [
    "The developer has full access to the Hyperledger Fabric and fabric-samples repositories.",
    "The work is performed by a single developer with expertise in Go and Hyperledger Fabric.",
    "Estimates include unit testing, code review, and basic integration verification but not extensive end-to-end network testing.",
    "The fabric-lib-go module will be created in a new GitHub repository under the Hyperledger organization with appropriate CI/CD setup.",
    "The existing Fabric codebase will be updated to use the new module in a coordinated change.",
    "The marbles02_private chaincode changes are limited to documentation and example export commands in the fabric-samples repository.",
    "No changes to the Fabric Go SDK are required as part of this increment; SDK maintainers will adopt the new libraries separately."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Refactor statebased package (U1)",
      "activity_description": "Analyze dependencies of ./core/chaincode/shim/ext/statebased, remove imports of fabric/comm, fabric/protoutil, pkg/errors, and transitive dependencies. Ensure only fabric protos remain. Update code, run tests, verify with go list.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Refactor entities package (U2)",
      "activity_description": "Analyze dependencies of ./core/chaincode/shim/ext/entities, remove all fabric package imports and transitive dependencies. Ensure only protos or standard library remain. Update code, run tests, verify with go list.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "Update marbles02_private chaincode (U3, U4)",
      "activity_description": "Edit the marbles02_private chaincode example in fabric-samples: add comments explaining the need for `tr -d \\\\` and modify export commands to include `tr -d \\\\` to avoid JSON parsing errors on Windows. Test the updated commands in a Windows-like environment.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "Create fabric-lib-go module structure",
      "activity_description": "Design and initialize a new Go module `github.com/hyperledger/fabric-lib-go` with subdirectories for protoutil, bccsp, msp, discovery. Set up go.mod, CI/CD pipelines, release process, and basic documentation.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize protoutil (U5)",
      "activity_description": "Extract protoutil package from Fabric into fabric-lib-go/protoutil. Remove internal dependencies, ensure it builds independently. Update Fabric to import from the new module. Run existing tests and add any missing unit tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize BCCSP (U6)",
      "activity_description": "Extract BCCSP (including sw, idemix, factory, etc.) into fabric-lib-go/bccsp. Refactor to eliminate internal Fabric dependencies. Update Fabric to depend on the new module. Ensure all cryptographic operations work correctly. Comprehensive testing required.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize MSP (U7)",
      "activity_description": "Extract MSP package into fabric-lib-go/msp. Remove dependencies on internal Fabric packages. Update Fabric to use the external module. Test identity management, signing, and verification flows.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A8",
      "activity_name": "Externalize discovery client (U8)",
      "activity_description": "Extract discovery client package into fabric-lib-go/discovery. Ensure it has no unwanted transitive dependencies. Update Fabric to import from the new module. Test service discovery functionality.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "Update Fabric codebase to use fabric-lib-go",
      "activity_description": "Replace all internal imports of protoutil, bccsp, msp, and discovery with the new fabric-lib-go module across the Fabric codebase. Update go.mod, resolve any version conflicts, run full test suite to ensure compatibility.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 204
  }
}

